cd /workspace/dataset
mk(){ n=$1; s='{}'; i=0; while [ $i -lt $n ]; do s="{\"allOf\":[$s]}"; i=$((i+1)); done; echo "$s"; }
lo=400; hi=900
while [ $((hi-lo)) -gt 8 ]; do mid=$(( (lo+hi)/2 )); if ./test5_executable --a 1 --b "$(mk $mid)" >/dev/null 2>&1; then lo=$mid; else hi=$mid; fi; done
echo "allOf ok<=$lo fail>=$hi"
mkp(){ n=$1; s='{}'; i=0; while [ $i -lt $n ]; do s="{\"properties\":{\"a\":$s}}"; i=$((i+1)); done; echo "$s"; }
mkia(){ n=$1; a='1'; i=0; while [ $i -lt $n ]; do a="{\"a\":$a}"; i=$((i+1)); done; echo "$a"; }
lo=100; hi=900
while [ $((hi-lo)) -gt 8 ]; do mid=$(( (lo+hi)/2 )); if ./test5_executable --a "$(mkia $mid)" --b "$(mkp $mid)" >/dev/null 2>&1; then lo=$mid; else hi=$mid; fi; done
